create table public.calendar_events (
  id uuid primary key default gen_random_uuid(),
  studio_id uuid references public.studios(id),
  code text not null,
  name text not null check(length(btrim(name)) between 1 and 160),
  starts_on date not null,
  ends_on date not null check(ends_on>=starts_on),
  kind text not null check(kind in ('oficial','civica','religiosa','tradicion','propia')),
  icon text not null,
  accent text not null,
  secondary text not null,
  message text not null,
  commemorated_on date,
  legal_basis text,
  days jsonb not null check(jsonb_typeof(days)='array'),
  created_by uuid references auth.users(id),
  created_at timestamptz not null default now(),
  unique nulls not distinct(studio_id,code,starts_on)
);
alter table public.calendar_events enable row level security;
create policy calendar_event_read on public.calendar_events for select to authenticated
using(studio_id is null or private.has_capability(studio_id,'schedule.read') or private.has_capability(studio_id,'student.booking.self'));
revoke all on public.calendar_events from public,anon,authenticated;
grant select on public.calendar_events to authenticated;
alter table public.studio_holiday_overrides add column calendar_event_id uuid references public.calendar_events(id);
create index calendar_events_date_lookup on public.calendar_events(starts_on,ends_on);
create index studio_holiday_overrides_event_lookup on public.studio_holiday_overrides(calendar_event_id);

create or replace function public.admin_create_calendar_event(p_studio_id uuid,p_name text,p_starts_on date,p_duration integer,p_icon text)
returns uuid language plpgsql security definer set search_path='' as $$
declare today date; e uuid; end_date date; calendar_days jsonb;
begin
  if (select auth.uid()) is null or not private.has_capability(p_studio_id,'settings.write') then raise exception 'forbidden'; end if;
  select (now() at time zone timezone)::date into today from public.studios where id=p_studio_id;
  if p_duration is null or p_duration not in (1,2,3,4,5,6,7,10,14) then raise exception 'invalid_duration'; end if;
  if nullif(btrim(p_name),'') is null or length(p_name)>160 then raise exception 'name_required'; end if;
  if p_icon is null or p_icon not in ('🎉','🎂','💃','🌸','✨','🏆','🎶','🌙') then raise exception 'invalid_icon'; end if;
  end_date:=p_starts_on+p_duration-1;
  if p_starts_on is null or p_starts_on<today or end_date>today+270 then raise exception 'date_outside_horizon'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_studio_id::text,7));
  if exists(select 1 from public.calendar_events where (studio_id is null or studio_id=p_studio_id) and starts_on<=end_date and ends_on>=p_starts_on) then raise exception 'calendar_event_overlap'; end if;
  select jsonb_agg(jsonb_build_object('date',p_starts_on+i,'name',btrim(p_name),'official',false,'suggest','normal') order by i)
    into calendar_days from generate_series(0,p_duration-1) i;
  insert into public.calendar_events(studio_id,code,name,starts_on,ends_on,kind,icon,accent,secondary,message,days,created_by)
    values(p_studio_id,gen_random_uuid()::text,btrim(p_name),p_starts_on,end_date,'propia',p_icon,'#0b7a55','#7c3aed',
      'Hola {nombre} '||p_icon||' El '||p_starts_on::text||' tenemos '||btrim(p_name)||'. Revisa los horarios en tu app.',calendar_days,(select auth.uid())) returning id into e;
  return e;
end;
$$;
revoke all on function public.admin_create_calendar_event(uuid,text,date,integer,text) from public,anon;
grant execute on function public.admin_create_calendar_event(uuid,text,date,integer,text) to authenticated;

create or replace function public.admin_configure_calendar_event(p_studio_id uuid,p_event_id uuid,p_days jsonb,p_message text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare e public.calendar_events%rowtype; item jsonb; official_id uuid; source text; result jsonb; total integer:=0; day_name text;
begin
  if (select auth.uid()) is null or not private.has_capability(p_studio_id,'settings.write') then raise exception 'forbidden'; end if;
  select * into e from public.calendar_events where id=p_event_id and (studio_id is null or studio_id=p_studio_id) for update;
  if not found then raise exception 'event_not_found'; end if;
  if jsonb_typeof(p_days) is distinct from 'array' or jsonb_array_length(p_days)<>jsonb_array_length(e.days) then raise exception 'all_days_required'; end if;
  if (select count(distinct value->>'date') from jsonb_array_elements(p_days))<>jsonb_array_length(e.days) then raise exception 'duplicate_day'; end if;
  for item in select value from jsonb_array_elements(p_days) loop
    if not exists(select 1 from jsonb_array_elements(e.days) d where d->>'date'=item->>'date') or item->>'mode' not in ('normal','closed','special') or item->>'mode' is null then raise exception 'invalid_day'; end if;
    if (item->>'date')::date < (select (now() at time zone timezone)::date from public.studios where id=p_studio_id) then raise exception 'past_day'; end if;
    select id into official_id from public.official_holidays where country_code='MX' and holiday_date=(item->>'date')::date and is_official limit 1;
    source:=case when official_id is not null then 'official' else 'manual' end;
    select d->>'name' into day_name from jsonb_array_elements(e.days) d where d->>'date'=item->>'date';
    result:=public.admin_save_calendar_day(p_studio_id,(item->>'date')::date,source,
      case when e.kind='propia' then 'Cierre del estudio · '||e.name when jsonb_array_length(e.days)>1 then e.name||' · '||day_name else 'Día festivo · '||e.name end,
      item->>'mode',coalesce(nullif(btrim(p_message),''),e.message),
      array(select value::uuid from jsonb_array_elements_text(coalesce(item->'keep','[]'::jsonb))),e.code,null,null);
    update public.studio_holiday_overrides set calendar_event_id=e.id,custom_name=case when source_kind='manual' then e.name else custom_name end where studio_id=p_studio_id and holiday_date=(item->>'date')::date;
    total:=total+1;
  end loop;
  return jsonb_build_object('ok',true,'days',total);
end;
$$;
revoke all on function public.admin_configure_calendar_event(uuid,uuid,jsonb,text) from public,anon;
grant execute on function public.admin_configure_calendar_event(uuid,uuid,jsonb,text) to authenticated;

